#include "anvil/ProjectHub.h"
#include <algorithm>
#include <cctype>
#include <fstream>
#include <sstream>
namespace anvil {
const char* ProjectHub::platformName(TargetPlatform p){switch(p){case TargetPlatform::Windows:return "Windows";case TargetPlatform::Android:return "Android";case TargetPlatform::IOS:return "iOS";case TargetPlatform::PlayStation:return "PlayStation (official SDK required)";case TargetPlatform::Xbox:return "Xbox (official SDK required)";case TargetPlatform::NintendoSwitch:return "Nintendo Switch (official SDK required)";}return "Unknown";}
std::vector<std::string> ProjectHub::templates(){return {"Blank","2D","3D"};}
bool ProjectHub::create(const std::filesystem::path& dir,const ProjectConfig& c,std::string* error){
 auto fail=[&](const std::string&s){if(error)*error=s;return false;};
 if(c.name.empty())return fail("Project name cannot be empty");
 for(char ch:c.name)if(!(std::isalnum(static_cast<unsigned char>(ch))||ch=='_'||ch=='-'||ch==' '))return fail("Project name contains unsupported characters");
 auto availableTemplates=templates();if(std::find(availableTemplates.begin(),availableTemplates.end(),c.templateName)==availableTemplates.end())return fail("Unknown project template: "+c.templateName);
 std::error_code ec;if(std::filesystem::exists(dir,ec))return fail("Destination already exists");
 auto staging=dir;staging += ".anvil-create-staging";if(std::filesystem::exists(staging,ec))return fail("Project staging directory already exists");
 auto make=[&](const char* p){std::filesystem::create_directories(staging/p,ec);return !ec;};
 if(!make("Assets")||!make("Assets/Textures")||!make("Assets/Models")||!make("Assets/Audio")||!make("Assets/Materials")||!make("Assets/Scenes")||!make("Config")||!make("Config/Platforms")||!make("Scripts")||!make("Build")){std::filesystem::remove_all(staging,ec);return fail("Cannot create project folders: "+ec.message());}
 std::vector<TargetPlatform> targets=c.targets.empty()?std::vector<TargetPlatform>{c.target}:c.targets;
 std::sort(targets.begin(),targets.end(),[](auto a,auto b){return static_cast<int>(a)<static_cast<int>(b);});targets.erase(std::unique(targets.begin(),targets.end()),targets.end());
 std::ofstream f(staging/"anvil.project");if(!f){std::filesystem::remove_all(staging,ec);return fail("Cannot write anvil.project");}
 f<<"ANVIL_PROJECT 2\nname="<<c.name<<"\ntemplate="<<c.templateName<<"\n";for(auto p:targets)f<<"target="<<platformName(p)<<"\n";f.close();
 if(!f){std::filesystem::remove_all(staging,ec);return fail("Failed writing project metadata");}
 std::ofstream settings(staging/"Config"/"project.ini");settings<<"version=1\nstartup_scene=Assets/Scenes/main.scene\n";settings.close();
 for(auto platform:targets){std::string file;switch(platform){case TargetPlatform::Windows:file="Windows.ini";break;case TargetPlatform::Android:file="Android.ini";break;case TargetPlatform::IOS:file="iOS.ini";break;case TargetPlatform::PlayStation:file="PlayStation.ini";break;case TargetPlatform::Xbox:file="Xbox.ini";break;case TargetPlatform::NintendoSwitch:file="NintendoSwitch.ini";break;}std::ofstream cfgFile(staging/"Config"/"Platforms"/file);cfgFile<<"platform="<<platformName(platform)<<"\n";bool closed=platform==TargetPlatform::PlayStation||platform==TargetPlatform::Xbox||platform==TargetPlatform::NintendoSwitch;cfgFile<<"requires_official_sdk="<<(closed?"true":"false")<<"\n";cfgFile<<"build_pipeline=not_configured\ninput_backend="<<(platform==TargetPlatform::Android||platform==TargetPlatform::IOS?"mobile-pending":"desktop-glfw")<<"\n";cfgFile.close();if(!cfgFile){std::filesystem::remove_all(staging,ec);return fail("Failed writing platform configuration: "+file);}}
 std::ofstream readme(staging/"README.md");readme<<"# "<<c.name<<"\n\nANVIL Engine project. Template: "<<c.templateName<<".\n\nTargets:\n";for(auto p:targets)readme<<"- "<<platformName(p)<<"\n";readme.close();
 if(!settings||!readme){std::filesystem::remove_all(staging,ec);return fail("Failed writing project configuration");}
 std::filesystem::rename(staging,dir,ec);if(ec){std::filesystem::remove_all(staging,ec);return fail("Cannot commit project directory: "+ec.message());}return true;
}
bool ProjectHub::validate(const std::filesystem::path& p,std::string* error){auto fail=[&](const std::string&s){if(error)*error=s;return false;};std::error_code ec;if(!std::filesystem::is_directory(p,ec))return fail("Project path is not a directory");std::ifstream f(p/"anvil.project");std::string first;if(!f||!std::getline(f,first)||(first!="ANVIL_PROJECT 1"&&first!="ANVIL_PROJECT 2"))return fail("Missing or unsupported anvil.project metadata");bool name=false;std::string line;while(std::getline(f,line))if(line.rfind("name=",0)==0&&line.size()>5)name=true;return name?true:fail("Project metadata does not contain a project name");}
std::vector<ProjectRecord> ProjectHub::discover(const std::filesystem::path& root){std::vector<ProjectRecord> out;std::error_code ec;if(!std::filesystem::is_directory(root,ec))return out;for(std::filesystem::directory_iterator it(root,ec),end;!ec&&it!=end;it.increment(ec)){if(!it->is_directory(ec)||!validate(it->path()))continue;std::ifstream f(it->path()/"anvil.project");std::string line,name=it->path().filename().string(),templ,target;while(std::getline(f,line)){if(line.rfind("name=",0)==0)name=line.substr(5);else if(line.rfind("template=",0)==0)templ=line.substr(9);else if(line.rfind("target=",0)==0){if(!target.empty())target+=", ";target+=line.substr(7);}}out.push_back({name,it->path(),templ,target});}std::sort(out.begin(),out.end(),[](const auto&a,const auto&b){return a.name<b.name;});return out;}
bool ProjectHub::addRecent(const std::filesystem::path& file,const std::filesystem::path& project,std::string* error){if(!validate(project,error))return false;std::error_code ec;if(!file.parent_path().empty())std::filesystem::create_directories(file.parent_path(),ec);if(ec){if(error)*error="Cannot create recent-project directory: "+ec.message();return false;}auto path=std::filesystem::weakly_canonical(project,ec);if(ec)path=project;std::vector<std::string> lines;{std::ifstream in(file);std::string line;while(std::getline(in,line))if(line!=path.generic_string())lines.push_back(line);}lines.insert(lines.begin(),path.generic_string());if(lines.size()>20)lines.resize(20);auto tmp=file;tmp+=".tmp";{std::ofstream out(tmp,std::ios::trunc);if(!out){if(error)*error="Cannot write recent-project list";return false;}for(const auto&line:lines)out<<line<<'\n';}std::filesystem::rename(tmp,file,ec);if(ec){std::filesystem::remove(tmp,ec);if(error)*error="Cannot commit recent-project list";return false;}return true;}
std::vector<ProjectRecord> ProjectHub::recent(const std::filesystem::path& file){std::vector<ProjectRecord> out;std::ifstream in(file);std::string line;while(std::getline(in,line)){std::filesystem::path p=line;std::string error;if(validate(p,&error)){auto records=discover(p.parent_path());for(auto&r:records)if(r.path==p){out.push_back(r);break;}}}return out;}
}
